10	export function describeCombos(combos: DescItem[][]): string {
11	  return combos
12	    .map(
13	      (c, i) =>
14	        `${i}. ` +
15	        c.map((it) => `${it.subcategory ?? it.category} (${it.colors.join("/")})`).join(" + "),
16	    )
17	    .join("\n");
18	}
19	
20	/**
21	 * Display budget for a look name — comfortably fits the "≤4 words" the prompt
22	 * asks for ("The Impeccable Charcoal Layer" = 29) with room to spare.
23	 */
24	export const NAME_MAX = 40;
25	
26	/**
27	 * Clamp a name to NAME_MAX on a word boundary.
28	 *
29	 * A name is decoration; the "why" is the product. This is a `transform`, not a
30	 * `.max()`, on purpose: the cap is never enforced on the model — CLAUDE.md's
31	 * `forStructuredOutput` strips `maxLength` because the API 400s on it — so a
32	 * hard bound here existed only as a post-hoc throw that failed the ENTIRE
33	 * generation and surfaced as "Couldn't reach the stylist". Repair, don't reject.
34	 */
35	export function clampName(raw: string): string {
36	  const s = raw.trim();
37	  if (s.length <= NAME_MAX) return s;
38	  const cut = s.slice(0, NAME_MAX);
39	  const lastSpace = cut.lastIndexOf(" ");
40	  return (lastSpace > 0 ? cut.slice(0, lastSpace) : cut).trimEnd();
41	}
