27	export function forStructuredOutput(node: unknown): unknown {
28	  if (Array.isArray(node)) return node.map(forStructuredOutput);
29	  if (node && typeof node === "object") {
30	    const out: Record<string, unknown> = {};
31	    for (const [key, value] of Object.entries(node)) {
32	      if (UNSUPPORTED_JSON_SCHEMA_KEYWORDS.has(key)) continue;
33	      out[key] = forStructuredOutput(value);
34	    }
35	    // Structured outputs require every object to forbid extra properties.
36	    if (out.type === "object" && !("additionalProperties" in out)) {
37	      out.additionalProperties = false;
38	    }
39	    return out;
40	  }
41	  return node;
42	}
